// frontend/src/App.js
import React, { useEffect, useState, useRef } from "react";
import axios from "axios";
import "./App.css";

function App() {
  const [message, setMessage] = useState("");
  const [chat, setChat] = useState([]);
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef();

  // optional: load history from backend when app mounts
  useEffect(() => {
    async function loadHistory() {
      try {
        const res = await axios.get("http://localhost:5000/api/history");
        if (res?.data?.history) {
          // backend returns items with sender 'user'/'bot'
          const mapped = res.data.history.map((m) => ({
            sender: m.sender === "user" ? "You" : "Bot",
            text: m.text,
            ts: new Date(m.timestamp).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
          }));
          setChat(mapped);
        }
      } catch (e) {
        // ignore if backend not available
      }
    }
    loadHistory();
  }, []);

  useEffect(() => {
    // auto-scroll to bottom when chat updates
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [chat, loading]);

  async function sendMessage(e) {
    e?.preventDefault();
    const text = message.trim();
    if (!text) return;
    setMessage("");
    const userMsg = { sender: "You", text, ts: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }) };
    setChat((c) => [...c, userMsg]);
    setLoading(true);

    try {
      const res = await axios.post("http://localhost:5000/api/chat", { message: text, history: chat }, { timeout: 10000 });
      const reply = res?.data?.reply ?? "Sorry, no reply.";
      setChat((c) => [...c, { sender: "Bot", text: reply, ts: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }) }]);
    } catch (err) {
      setChat((c) => [...c, { sender: "Bot", text: "Error: could not reach backend", ts: "" }]);
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="page-bg">
      <div className="phone-shell">
        <header className="phone-header">
          <button className="back-btn">‹</button>
          <div className="title-area">
            <div className="title">Chat with NOVA</div>
            <div className="subtitle">Online</div>
          </div>
          <div className="menu">⋮</div>
        </header>

        <main className="chat-area" ref={scrollRef}>
          {chat.length === 0 && (
            <div className="welcome">
              <h2>How can we help you?</h2>
              <p>We are available 24/7 to help clarify any confusion you have on our product and ensure you have a seamless experience.</p>
            </div>
          )}

          {chat.map((m, i) => (
            <div
              key={i}
              className={m.sender === "You" ? "bubble-row user" : "bubble-row bot"}
            >
              <div className={m.sender === "You" ? "bubble user-bubble" : "bubble bot-bubble"}>
                <div className="bubble-text">{m.text}</div>
                {m.ts && <div className="time">{m.ts}</div>}
              </div>
            </div>
          ))}

          {loading && (
            <div className="bubble-row bot">
              <div className="bubble bot-bubble">
                <div className="bubble-text">Typing…</div>
              </div>
            </div>
          )}
        </main>

        <form className="chat-input-area" onSubmit={sendMessage}>
          <input
            className="chat-input"
            placeholder="Type your message..."
            value={message}
            onChange={(e) => setMessage(e.target.value)}
          />
          <button type="submit" className="send-btn">➤</button>
        </form>
      </div>
    </div>
  );
}

export default App;
